const DARK_TYPES = ['hook', 'cta', 'payoff'];
const SWIPE_HINT = ['hook', 'stakes'];
const DENSE_AT = 5;

function logoMarkup(slideType, g) {
  const src = DARK_TYPES.includes(slideType)
    ? (g.LOGO_URL_NEGATIVE || '')
    : (g.LOGO_URL || '');
  return src
    ? `<img class="logo-img" src="${esc(src)}" alt="TU/e">`
    : `<span class="logo-ph">TU/e logo</span>`;
}

function renderSlide(s, total, g) {
  const blocks = Array.isArray(s.blocks) ? s.blocks : [];
  const weight = slideWeight(blocks, s.headline, s.slide_type);
  const hasChip = !!s.kicker;
  const cls = [
    'slide',
    'slide--' + esc(s.slide_type),
    weight >= DENSE_AT ? 'slide--dense' : '',
  ].filter(Boolean).join(' ');

  return `
  <div class="${cls}">
    <div class="top">
      <span class="progress">${s.slide_number}/${total}</span>
    </div>
    <div class="content${hasChip ? '' : ' content--nochip'}">
      <div class="fit">
        ${hasChip ? `<span class="chip">${esc(s.kicker)}</span>` : ''}
        <h1 class="headline">${headlineHtml(s.headline, s.accent)}</h1>
        <div class="blocks">${blocks.map(renderBlock).join('')}</div>
      </div>
    </div>
    <div class="footer">
      <span class="handle">${esc(g.FACULTY_NAME)}</span>
      <div class="footer-right">
        ${SWIPE_HINT.includes(s.slide_type) ? `<span class="swipe">Swipe &rarr;</span>` : ''}
        <div class="logo">${logoMarkup(s.slide_type, g)}</div>
      </div>
    </div>
  </div>`;
}

function buildCarouselHtml(parent, g) {
  const total = parent.total_slides || parent.slides.length;
  const slidesHtml = parent.slides.map((s) => renderSlide(s, total, g)).join('\n');
  return `<!doctype html>
<html><head><meta charset="utf-8"><style>${stylesheet(g)}</style></head>
<body>
${slidesHtml}
</body></html>`;
}

// ============================================================================
//  n8n GLUE
// ============================================================================

const parent = $json;
const g = $('Globals').first().json;
const html = buildCarouselHtml(parent, g);

return [{
  json: {
    _parent: { ...parent, slides: undefined },
    slides: parent.slides.map((s) => ({
      slide_number: s.slide_number,
      slide_type: s.slide_type,
      density: slideWeight(s.blocks, s.headline, s.slide_type),
    })),
    total_slides: parent.total_slides || parent.slides.length,
    html,
  },
}];

// Variant test: we only need the images on Drive for the supervisor to look at,
// so the renderer's public URLs are ignored here. One item per slide.

const resp = $json;
const build = $('Build Carousel HTML').first().json;
const meta = build.slides || [];
const images = resp.images || [];
const fits = Array.isArray(resp.fits) ? resp.fits : [];

if (images.length !== meta.length) {
  throw new Error(`Renderer returned ${images.length} images but expected ${meta.length}`);
}

const parent = { ...build._parent, _fits: fits };

const out = [];
for (let i = 0; i < meta.length; i++) {
  const m = meta[i];
  const img = images[i];
  const b64 = typeof img === 'string' ? img : (img.image_base64 || img.base64 || img.data);
  if (!b64) throw new Error('No image data for slide ' + m.slide_number);
  const buffer = Buffer.from(b64, 'base64');
  const binaryData = await this.helpers.prepareBinaryData(
    buffer, `slide_${m.slide_number}.jpg`, 'image/jpeg'
  );
  out.push({
    json: {
      _parent: parent,
      variant_id: parent.variant_id,
      variant_slug: parent.variant_slug,
      slide_number: m.slide_number,
      slide_type: m.slide_type,
      density: m.density,
      fit: fits[i] ?? 1,
    },
    binary: { data: binaryData },
  });
}
return out;

// Final summary, printed in the execution log so you can see at a glance
// what the five variants did differently before you open the folder.

return [{ json: {
  done: true,
  message: 'All five variants rendered and uploaded. Open the Drive folder; files sort A to E.',
} }];
